struct Item {
    int value;
    int index;
    Item(int v, int i) : value(v), index(i) {}
};

class Solution {
public:
    std::vector<int> twoSum(std::vector<int>& nums, int target) {
        std::vector<Item> items;
        for (int i = 0; i < (int)nums.size(); ++i) items.emplace_back(nums[i], i);
        std::sort(items.begin(), items.end(), [](const Item& a, const Item& b) { return a.value < b.value; });
        int lo = 0, hi = (int)items.size() - 1;
        while (lo < hi) {
            int sum = items[lo].value + items[hi].value;
            if (sum == target) {
                std::vector<int> result{items[lo].index, items[hi].index};
                std::sort(result.begin(), result.end());
                return result;
            }
            if (sum < target) {
                ++lo;
            } else {
                --hi;
            }
        }
        return {};
    }
};

