    double number;
    Value(const std::string& s) : text(s), number(0) {}
    Value(double d) : number(d) {}
};

class Solution {
public:
    bool detectArbitrage(std::vector<std::string>& currencies, std::vector<std::vector<Value>>& rates) {
        std::unordered_map<std::string, int> id;
        for (int i = 0; i < (int)currencies.size(); ++i) id[currencies[i]] = i;
        int n = currencies.size();
        std::vector<double> dist(n, 0.0);
        for (int round = 0; round < n; ++round) {
            bool changed = false;
            for (auto& rate : rates) {
                int from = id[rate[0].text];
                int to = id[rate[1].text];
                double weight = -std::log(rate[2].number);
                if (dist[from] + weight < dist[to] - 1e-12) {
                    dist[to] = dist[from] + weight;
                    changed = true;
                }
            }
            if (!changed) return false;
        }
        return true;
    }
};

