class NumArray {
public:
    std::vector<int> prefix;

    NumArray(std::vector<int>& nums) : prefix(nums.size() + 1, 0) {
        for (size_t i = 0; i < nums.size(); ++i) prefix[i + 1] = prefix[i] + nums[i];
