class ParkingLot {
public:
    std::unordered_map<std::string, int> free;

    ParkingLot(int small, int medium, int large) {
        free["small"] = small;
        free["medium"] = medium;
        free["large"] = large;
    }

    bool park(std::string size) {
        auto slot = free.find(size);
        if (slot == free.end() || slot->second == 0) return false;
        --slot->second;
        return true;
    }

    int available(std::string size) {
        return free.count(size) ? free[size] : 0;
    }
};

